        }
    }

    fn make_signal(name: &str) -> SignalDecl {
        SignalDecl {
            name: name.to_string(),
            payload: Some(json!({ "type": "object" })),
            subid: format!("evt.service.testplugin.{}@v1", name.to_lowercase()),
        }
    }

    fn make_schema(name: &str, methods: &[&str], signals: &[&str]) -> PluginSchema {
        let mut method_map = HashMap::new();
        for m in methods {
            method_map.insert(m.to_string(), make_method(m));
        }
        let signal_vec: Vec<SignalDecl> = signals.iter().map(|s| make_signal(s)).collect();
        PluginSchema::builder(name)
            .methods(method_map)
            .signals(signal_vec)
            .guarantees(PluginCapabilities::default())
            .build()
    }

    /// Writes the combined monolith (the exact format `op-projection`'s
    /// shm_writer emits: a JSON object keyed by `plugin_id`) to `dir`.
    fn write_monolith_file(dir: &Path, schemas: &HashMap<String, PluginSchema>) -> PathBuf {
        let path = dir.join("live-schema.json");
        fs::write(&path, serde_json::to_vec_pretty(schemas).unwrap()).unwrap();
        path
    }

    /// Loads a single plugin route by writing a monolith and reading it back.
    fn route_for(name: &str, methods: &[&str], signals: &[&str]) -> PluginRoute {
        let tmp = tempfile::tempdir().expect("tempdir");
        let mut schemas = HashMap::new();
        schemas.insert(name.to_string(), make_schema(name, methods, signals));
        let monolith = write_monolith_file(tmp.path(), &schemas);
        let routes = SchemaRouter::load_routes_from(&monolith, &tmp.path().join("none"));
        routes.get(name).expect("route present").clone()
    }

    // ── VAL-BRIDGE-003: one SchemaBackedInterface per plugin from SHM ──

    #[test]
    fn bridge_registers_object_per_plugin_from_shm() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let mut schemas = HashMap::new();
        schemas.insert(
            "wireguard".to_string(),
            make_schema("wireguard", &["SetKey", "GetStatus"], &["KeyRotated"]),
        );
        schemas.insert(
            "xray".to_string(),
            make_schema("xray", &["Reload"], &[]),
        );
        schemas.insert(
            "unix_socket".to_string(),
            make_schema("unix_socket", &[], &["Connected"]),
        );
        let monolith = write_monolith_file(tmp.path(), &schemas);
        let absent_per_plugin = tmp.path().join("no-such-dir");

        let routes = SchemaRouter::load_routes_from(&monolith, &absent_per_plugin);

        assert_eq!(routes.len(), 3, "one route per plugin from the SHM monolith");
        for id in ["wireguard", "xray", "unix_socket"] {
            let route = routes
                .get(id)
                .unwrap_or_else(|| panic!("route {id} must be present"));
            assert_eq!(route.plugin_id, id);
            assert_eq!(
                route.dbus_path,
                canonical::plugin_path(id),
                "registered at /org/opdbus/v1/plugins/<plugin_id>"
            );
            assert_eq!(route.dbus_interface, canonical::plugin_interface(id));
            assert_eq!(route.dbus_destination, BASE_SERVICE_NAME);

            // The bridge builds one SchemaBackedInterface per plugin for registration.
            let iface = SchemaBackedInterface::new(id.to_string(), route.clone());
            assert_eq!(iface.plugin_id(), id);
            assert_eq!(iface.object_path(), canonical::plugin_path(id));
            assert_eq!(iface.interface_name(), canonical::plugin_interface(id));
        }
    }

    // ── VAL-BRIDGE-004: every MethodDecl exposed as a callable D-Bus method ──

    #[test]
    fn bridge_exposes_all_declared_methods() {
        let methods = ["SetKey", "GetStatus", "RotateKey"];
        let route = route_for("wireguard", &methods, &[]);
        let iface = SchemaBackedInterface::new("wireguard".to_string(), route);

        let exposed = iface.exposed_methods();
        assert_eq!(
            exposed.len(),
            methods.len(),
            "every declared MethodDecl is exposed"
        );
        for m in methods {
            assert!(iface.exposes_method(m), "method {m} exposed as callable");
            assert!(exposed.contains(&m.to_string()));
        }
        // Methods are exposed on interface org.opdbus.v1.Plugin.<PluginName>.
        assert_eq!(
            iface.interface_name(),
            canonical::plugin_interface("wireguard")
        );
        // A method not in the capability surface is not exposed.
        assert!(!iface.exposes_method("NonexistentMethod"));
    }

