    #[tokio::test]
    async fn bridge_call_rejects_undeclared_method() {
        let state_dir = test_state_dir();
        let route = route_for("wireguard", &["SetKey"], &[]);
        let iface = SchemaBackedInterface::with_shm_state_dir(
            "wireguard".to_string(),
            route,
            &state_dir,
        );

        let unknown = iface
            .call("NotDeclared".to_string(), "{}".to_string())
            .await;
        assert!(
            matches!(unknown, Err(zbus::fdo::Error::UnknownMethod(_))),
            "undeclared method must be rejected as UnknownMethod"
        );

        let declared = iface.call("SetKey".to_string(), "{}".to_string()).await;
        assert!(
            declared.is_ok(),
            "declared method must be accepted by the dispatcher"
        );

        cleanup(&state_dir);
    }

