    #[test]
    fn bridge_falls_back_to_per_plugin_schemas() {
        let tmp = tempfile::tempdir().expect("tempdir");
        // Monolith path is never written → absent.
        let monolith = tmp.path().join("live-schema.json");
        let per_plugin = tmp.path().join("schemas");
        fs::create_dir_all(&per_plugin).unwrap();
        let wg = make_schema("wireguard", &["SetKey"], &["KeyRotated"]);
        fs::write(
            per_plugin.join("wireguard.json"),
            serde_json::to_vec_pretty(&wg).unwrap(),
        )
        .unwrap();

        let routes = SchemaRouter::load_routes_from(&monolith, &per_plugin);

        assert_eq!(
            routes.len(),
            1,
            "fallback loads per-plugin schemas when the monolith is absent"
        );
        let route = routes.get("wireguard").expect("fallback route present");
        assert!(route.methods.contains_key("SetKey"));
        assert!(route.signals.contains_key("KeyRotated"));
    }

    // ── R4.2: monolith takes precedence over per-plugin fallback ──

    #[test]
    fn bridge_prefers_monolith_over_per_plugin_fallback() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let mut schemas = HashMap::new();
        schemas.insert(
            "wireguard".to_string(),
            make_schema("wireguard", &["FromMonolith"], &[]),
        );
        let monolith = write_monolith_file(tmp.path(), &schemas);
        let per_plugin = tmp.path().join("schemas");
        fs::create_dir_all(&per_plugin).unwrap();
        let wg = make_schema("wireguard", &["FromPerPlugin"], &[]);
        fs::write(
            per_plugin.join("wireguard.json"),
            serde_json::to_vec_pretty(&wg).unwrap(),
        )
        .unwrap();

        let routes = SchemaRouter::load_routes_from(&monolith, &per_plugin);
        let route = routes.get("wireguard").expect("route present");
        assert!(
            route.methods.contains_key("FromMonolith"),
            "monolith definition takes precedence"
        );
        assert!(!route.methods.contains_key("FromPerPlugin"));
    }
}

