/// Load all plugin routes from the combined monolith, falling back to
/// per-plugin schema files for any plugin not present in the monolith.
///
/// The monolith (`live-schema.json`) is authoritative: when a plugin is
/// defined in both sources, the monolith definition wins. Per-plugin files
/// are read from `per_plugin_dir` only as a fallback (e.g. when the
/// monolith is missing or does not yet include a plugin).
///
/// This is a direct read from shared memory — no polling, no watchers.
pub fn load_routes_from(
    monolith_path: &Path,
    per_plugin_dir: &Path,
) -> HashMap<String, PluginRoute> {
    let mut routes = HashMap::new();
    if let Some(monolith_routes) = Self::load_from_monolith_at(monolith_path) {
        for (id, route) in monolith_routes {
            routes.insert(id, route);
        }
    }
    if let Some(per_plugin_routes) = Self::load_from_per_plugin_dir_at(per_plugin_dir) {
        for (id, route) in per_plugin_routes {
            routes.entry(id).or_insert(route);
        }
    }
    routes
}

fn load_from_monolith_at(path: &Path) -> Option<HashMap<String, PluginRoute>> {
    let bytes = std::fs::read(path).ok()?;
    let root: JsonValue = serde_json::from_slice(&bytes).ok()?;
    let catalog = root.as_object()?;

    let mut routes = HashMap::new();
    for (plugin_id, schema_value) in catalog {
        let schema = match schema_value {
            JsonValue::Array(arr) => match arr.first() {
                Some(s) => s,
                None => continue,
            },
            JsonValue::Object(_) => schema_value,
            _ => continue,
        };
        let route = Self::build_route(plugin_id, schema);
        routes.insert(plugin_id.clone(), route);
    }
    Some(routes)
}

fn load_from_per_plugin_dir_at(dir: &Path) -> Option<HashMap<String, PluginRoute>> {
    if !dir.is_dir() {
