/// Extracts declared signals from a plugin schema.
///
/// `signals` serializes as an array of `SignalDecl` objects; this builds a
/// map keyed by each signal's `name` for O(1) membership checks during
/// emission.
fn extract_signals(schema: &JsonValue) -> HashMap<String, JsonValue> {
    let mut signals = HashMap::new();
    if let Some(signal_arr) = schema.get("signals").and_then(|s| s.as_array()) {
        for decl in signal_arr {
            if let Some(name) = decl.get("name").and_then(|n| n.as_str()) {
                signals.insert(name.to_string(), decl.clone());
            }
        }
    }
    signals
}

